from starlette.middleware import Middleware
from starlette.middleware.exceptions import ExceptionMiddleware as StarletteExceptionMiddleware
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.types import Receive, Send, Scope, Message

class CustomExceptionMiddleware(StarletteExceptionMiddleware):
    async def dispatch(self, request: Request, call_next):
        try:
            return await call_next(request)
        except Exception as e:
            response = await self.handle_exception(request, e)
            return response

    async def handle_exception(self, request: Request, exc: Exception) -> JSONResponse:
        status_code = 500
        detail = str(exc)
        return JSONResponse(content={"error": detail}, status_code=status_code)

def build_exception_middleware(app):
    return Middleware(CustomExceptionMiddleware, handlers={})
